    {id:"chicken-rice-bowl",name:{vi:"Cơm gà áp chảo",en:"Pan-seared chicken rice bowl"},mealType:"lunch",time:25,cost:32000,servings:1,photo:photos.chicken,cuisine:"Vietnamese",tags:["high-protein","meal-prep"],allergens:[],ingredients:[["chicken",150,"g"],["rice",150,"g"],["cucumber",50,"g"],["lettuce",30,"g"],["soy-sauce",8,"ml"],["garlic",1,"tép"],["oil",5,"ml"]],steps:{vi:["Ướp gà với nước tương, tỏi băm và chút tiêu trong 10 phút.","Nấu cơm; rửa sạch rau xà lách và dưa leo rồi cắt lát.","Áp chảo gà với ít dầu, mỗi mặt 5–6 phút đến khi chín hoàn toàn.","Thái gà, xếp lên cơm cùng rau và rưới phần nước sốt trong chảo."],en:["Marinate chicken with soy sauce, minced garlic and pepper for ten minutes.","Cook rice; wash and slice the lettuce and cucumber.","Pan-sear chicken in a little oil, 5–6 minutes per side until fully cooked.","Slice the chicken and serve over rice with vegetables and pan juices."]}},
    {id:"pork-caramel",name:{vi:"Thịt heo kho tiêu",en:"Peppery caramelized pork"},mealType:"dinner",time:35,cost:30000,servings:2,photo:photos.rice,cuisine:"Vietnamese",tags:["meal-prep","comfort"],allergens:["soy"],ingredients:[["pork",250,"g"],["sugar",10,"g"],["fish-sauce",12,"ml"],["garlic",2,"tép"],["scallion",5,"g"],["chili",1,"trái"]],steps:{vi:["Thái thịt thành miếng vừa ăn; ướp với nước mắm, tiêu và tỏi 10 phút.","Thắng đường với 1 thìa nước trên lửa nhỏ đến màu cánh gián.","Cho thịt vào đảo đều, thêm nước xâm xấp và đun sôi.","Kho nhỏ lửa 20–25 phút đến khi thịt mềm, nước sệt; rắc hành và tiêu."],en:["Cut pork into bite-size pieces; marinate with fish sauce, pepper and garlic for ten minutes.","Melt sugar with a spoonful of water over low heat until amber.","Coat pork in the caramel, add water to cover halfway and bring to a simmer.","Braise 20–25 minutes until tender and glossy; finish with scallion and pepper."]}},
    {id:"chicken-porridge",name:{vi:"Cháo gà gừng",en:"Ginger chicken rice porridge"},mealType:"breakfast",time:40,cost:28000,servings:2,photo:photos.soup,cuisine:"Vietnamese",tags:["comfort","meal-prep"],allergens:[],ingredients:[["rice",100,"g"],["chicken",150,"g"],["ginger",10,"g"],["scallion",10,"g"],["salt",3,"g"],["fish-sauce",5,"ml"]],steps:{vi:["Vo gạo, rang sơ trong nồi khô 2 phút để cháo thơm hơn.","Thêm 1 lít nước, gừng thái lát và nấu nhỏ lửa 25 phút.","Cho gà vào luộc trong cháo đến khi chín; vớt ra xé sợi.","Nêm vừa ăn, cho gà trở lại nồi và thêm hành lá trước khi dùng."],en:["Rinse the rice and toast it in a dry pot for two minutes for a nutty aroma.","Add one litre of water and sliced ginger; simmer for 25 minutes.","Poach chicken in the porridge until cooked, then remove and shred.","Season to taste, return chicken to the pot and garnish with scallion."]}},
    {id:"garlic-noodles",name:{vi:"Mì xào rau tỏi",en:"Garlic vegetable noodles"},mealType:"dinner",time:15,cost:16000,servings:1,photo:photos.noodles,cuisine:"Asian",tags:["quick","vegetarian"],allergens:["gluten","soy"],ingredients:[["instant-noodle",1,"gói"],["cabbage",50,"g"],["carrot",30,"g"],["garlic",2,"tép"],["soy-sauce",8,"ml"],["oil",5,"ml"]],steps:{vi:["Chần mì trong nước sôi 2 phút, vớt ra để ráo.","Thái mỏng bắp cải, cà rốt; băm nhỏ tỏi.","Phi tỏi, xào rau trên lửa lớn 2 phút rồi cho mì vào.","Nêm nước tương và đảo thêm 1–2 phút; ăn nóng."],en:["Blanch noodles in boiling water for two minutes; drain well.","Thinly slice cabbage and carrot; mince the garlic.","Sauté garlic, stir-fry vegetables over high heat for two minutes, then add noodles.","Season with soy sauce, toss for another minute and serve hot."]}},
    {id:"omelette-scallion",name:{vi:"Trứng chiên hành",en:"Scallion omelette"},mealType:"breakfast",time:8,cost:9000,servings:1,photo:photos.toast,cuisine:"Vietnamese",tags:["quick","budget"],allergens:["eggs"],ingredients:[["egg",2,"quả"],["scallion",10,"g"],["fish-sauce",3,"ml"],["oil",5,"ml"]],steps:{vi:["Đập trứng vào bát, thêm hành lá cắt nhỏ và nước mắm.","Đánh đều hỗn hợp đến khi lòng đỏ và lòng trắng hòa quyện.","Làm nóng dầu, đổ trứng vào chảo và chiên lửa vừa.","Khi mặt dưới vàng, gấp đôi hoặc lật nhẹ; dùng kèm cơm hay bánh mì."],en:["Beat eggs with finely sliced scallion and fish sauce.","Whisk until yolks and whites are combined.","Heat oil and pour in the egg mixture over medium heat.","Fold or flip once the base is golden; serve with rice or bread."]}},
    {id:"tuna-sandwich",name:{vi:"Bánh mì kẹp cá ngừ",en:"Tuna cucumber sandwich"},mealType:"breakfast",time:10,cost:24000,servings:1,photo:photos.toast,cuisine:"Western",tags:["quick","no-cook"],allergens:["seafood","gluten"],ingredients:[["bread",1,"ổ"],["tuna",0.5,"hộp"],["cucumber",30,"g"],["lettuce",15,"g"],["lime",0.5,"quả"]],steps:{vi:["Để ráo cá ngừ, trộn cùng nước cốt chanh và một nhúm tiêu.","Rửa sạch xà lách, thái dưa leo thành lát mỏng.","Rạch bánh mì, xếp rau và dưa leo vào trong.","Thêm cá ngừ, ép nhẹ và dùng ngay để bánh mì còn giòn."],en:["Drain tuna and mix with lime juice and a pinch of pepper.","Wash lettuce and slice cucumber thinly.","Split the baguette and layer in the vegetables.","Add tuna, press gently and serve while the bread is crisp."]}},
    {id:"tomato-beef-pasta",name:{vi:"Mì Ý bò sốt cà chua",en:"Beef tomato pasta"},mealType:"dinner",time:30,cost:42000,servings:2,photo:photos.pasta,cuisine:"Western",tags:["comfort","meal-prep"],allergens:["gluten"],ingredients:[["pasta",160,"g"],["beef",120,"g"],["tomato",2,"quả"],["onion",0.5,"củ"],["garlic",2,"tép"],["oil",8,"ml"]],steps:{vi:["Luộc mì theo hướng dẫn trên gói, giữ lại ½ cốc nước luộc.","Băm hành tây, tỏi; thái cà chua và bò thành miếng nhỏ.","Phi hành tỏi, xào bò nhanh tay rồi thêm cà chua và ½ cốc nước.","Nấu sốt 10 phút, nêm vừa ăn; trộn mì với sốt và dùng nóng."],en:["Cook pasta according to the packet; reserve half a cup of pasta water.","Dice onion and garlic; chop tomatoes and beef into small pieces.","Sauté onion and garlic, sear beef quickly, then add tomatoes and pasta water.","Simmer the sauce for ten minutes, season and toss with pasta."]}},
    {id:"sweet-potato-yogurt",name:{vi:"Khoai lang và sữa chua",en:"Sweet potato with yogurt"},mealType:"snack",time:20,cost:12000,servings:1,photo:photos.bowl,cuisine:"Vietnamese",tags:["vegetarian","snack","budget"],allergens:["dairy"],ingredients:[["sweet-potato",1,"củ"],["yogurt",1,"hũ"]],steps:{vi:["Rửa sạch khoai lang, dùng nĩa chọc vài lỗ nhỏ trên vỏ.","Hấp 15–20 phút hoặc đến khi xiên đũa qua dễ dàng.","Để nguội bớt, bóc vỏ và cắt miếng.","Dùng cùng một hũ sữa chua như bữa phụ no lâu."],en:["Wash the sweet potato and prick its skin a few times with a fork.","Steam for 15–20 minutes until a skewer slides in easily.","Cool slightly, peel and cut into chunks.","Serve with yogurt for a filling snack."]}},
    {id:"banana-oat-pancake",name:{vi:"Bánh chuối yến mạch",en:"Banana oat pancakes"},mealType:"breakfast",time:18,cost:18000,servings:2,photo:photos.toast,cuisine:"Western",tags:["vegetarian","quick"],allergens:["eggs","gluten"],ingredients:[["banana",1,"quả"],["oats",60,"g"],["egg",1,"quả"],["milk",40,"ml"],["oil",5,"ml"]],steps:{vi:["Nghiền chuối chín bằng nĩa; trộn cùng trứng, sữa và yến mạch.","Để hỗn hợp nghỉ 5 phút để yến mạch mềm.","Phết một lớp dầu mỏng lên chảo chống dính, múc từng bánh nhỏ.","Chiên lửa nhỏ 2 phút mỗi mặt đến khi vàng; dùng với trái cây."],en:["Mash the ripe banana and mix with egg, milk and oats.","Rest the batter for five minutes to soften the oats.","Lightly oil a non-stick pan and spoon in small pancakes.","Cook over low heat for about two minutes per side until golden; serve with fruit."]}},
    {id:"pumpkin-soup",name:{vi:"Súp bí đỏ sữa tươi",en:"Creamy pumpkin soup"},mealType:"dinner",time:30,cost:22000,servings:2,photo:photos.soup,cuisine:"Western",tags:["vegetarian","meal-prep"],allergens:["dairy"],ingredients:[["pumpkin",250,"g"],["onion",0.5,"củ"],["milk",100,"ml"],["oil",5,"ml"],["salt",2,"g"]],steps:{vi:["Gọt vỏ bí đỏ, bỏ hạt và cắt thành khối nhỏ; thái hành tây.","Phi hành với dầu đến thơm, thêm bí và 400 ml nước.","Nấu 15 phút đến khi bí mềm, sau đó nghiền mịn.","Thêm sữa, đun nóng nhẹ và nêm muối; không đun sôi mạnh."],en:["Peel and cube the pumpkin; remove seeds and slice the onion.","Sauté onion in oil, add pumpkin and 400 ml water.","Simmer for 15 minutes until tender, then blend or mash until smooth.","Stir in milk, warm gently and season with salt without boiling hard."]}},
    {id:"cucumber-egg-salad",name:{vi:"Salad trứng dưa leo",en:"Cucumber egg salad"},mealType:"lunch",time:15,cost:19000,servings:1,photo:photos.salad,cuisine:"Western",tags:["quick","vegetarian"],allergens:["eggs"],ingredients:[["egg",2,"quả"],["cucumber",1,"quả"],["lettuce",30,"g"],["lime",0.5,"quả"],["sugar",2,"g"]],steps:{vi:["Luộc trứng 9 phút, ngâm nước mát rồi bóc vỏ và bổ đôi.","Rửa rau, cắt dưa leo thành lát; để thật ráo.","Pha nước cốt chanh với 1 thìa nước, đường và chút muối.","Xếp rau và trứng ra đĩa, rưới nước sốt ngay trước khi ăn."],en:["Boil eggs for nine minutes, cool in water, peel and halve.","Wash greens, slice cucumber and dry thoroughly.","Whisk lime juice with a spoonful of water, sugar and a pinch of salt.","Arrange greens and eggs; dress just before eating."]}},
    {id:"shrimp-fried-rice",name:{vi:"Cơm chiên tôm",en:"Shrimp fried rice"},mealType:"lunch",time:20,cost:35000,servings:1,photo:photos.rice,cuisine:"Asian",tags:["quick","high-protein"],allergens:["seafood","eggs","soy"],ingredients:[["rice",150,"g"],["shrimp",80,"g"],["egg",1,"quả"],["carrot",30,"g"],["scallion",5,"g"],["soy-sauce",5,"ml"]],steps:{vi:["Bóc vỏ tôm, bỏ chỉ lưng; thái hạt lựu cà rốt.","Làm nóng chảo, xào tôm đến vừa chuyển hồng rồi để riêng.","Đảo trứng cho tơi, thêm cà rốt và cơm nguội vào chảo.","Cho tôm và nước tương trở lại chảo, đảo nóng 2 phút rồi rắc hành."],en:["Peel and devein shrimp; dice the carrot.","Sear shrimp until just pink and set aside.","Scramble the egg, then add carrot and cold cooked rice.","Return shrimp with soy sauce, toss for two minutes and garnish with scallion."]}},
    {id:"beef-stir-fry",name:{vi:"Bò xào hành tây",en:"Beef and onion stir-fry"},mealType:"dinner",time:18,cost:39000,servings:1,photo:photos.bowl,cuisine:"Vietnamese",tags:["quick","high-protein"],allergens:["soy"],ingredients:[["beef",120,"g"],["onion",0.5,"củ"],["bell-pepper",0.5,"trái"],["garlic",1,"tép"],["soy-sauce",8,"ml"],["oil",5,"ml"]],steps:{vi:["Thái bò ngang thớ thật mỏng; ướp nước tương, tỏi và tiêu 10 phút.","Thái hành tây và ớt chuông thành miếng vừa ăn.","Làm nóng chảo thật kỹ, xào bò nhanh tay trong 1–2 phút rồi trút ra.","Xào rau củ vừa mềm, cho bò trở lại đảo đều rồi tắt bếp."],en:["Slice beef thinly across the grain; marinate with soy, garlic and pepper for ten minutes.","Cut onion and bell pepper into bite-size pieces.","Heat the pan well, sear beef for 1–2 minutes and remove.","Stir-fry vegetables until just tender, return beef, toss and turn off the heat."]}},
    {id:"pork-cabbage-soup",name:{vi:"Canh bắp cải thịt bằm",en:"Cabbage soup with ground pork"},mealType:"dinner",time:25,cost:23000,servings:2,photo:photos.soup,cuisine:"Vietnamese",tags:["budget","comfort"],allergens:[],ingredients:[["minced-pork",100,"g"],["cabbage",150,"g"],["carrot",50,"g"],["scallion",5,"g"],["salt",3,"g"],["fish-sauce",5,"ml"]],steps:{vi:["Bắp cải thái miếng vừa ăn, cà rốt thái lát mỏng.","Đun sôi 700 ml nước; thả thịt bằm vào và khuấy tơi.","Hớt bọt, thêm cà rốt và nấu 5 phút rồi cho bắp cải vào.","Nêm nước mắm, muối vừa ăn; đun thêm 3 phút và rắc hành."],en:["Cut cabbage into bite-size pieces and slice the carrot thinly.","Bring 700 ml water to a boil, add ground pork and break it up.","Skim foam, add carrot for five minutes, then add cabbage.","Season with fish sauce and salt; simmer three more minutes and garnish with scallion."]}},
    {id:"vegetable-curry",name:{vi:"Cà ri rau củ nước cốt dừa",en:"Coconut vegetable curry"},mealType:"dinner",time:35,cost:28000,servings:2,photo:photos.soup,cuisine:"Asian",tags:["vegetarian","meal-prep"],allergens:[],ingredients:[["potato",100,"g"],["carrot",80,"g"],["pumpkin",100,"g"],["coconut-milk",100,"ml"],["curry-powder",10,"g"],["onion",0.5,"củ"]],steps:{vi:["Gọt vỏ khoai tây, cà rốt, bí đỏ; cắt khối đều nhau.","Phi hành, cho bột cà ri vào đảo thơm khoảng 30 giây.","Thêm rau củ và 400 ml nước, đậy nắp nấu 15 phút.","Rót nước cốt dừa, nêm muối và nấu thêm 5 phút đến khi rau mềm."],en:["Peel potatoes, carrots and pumpkin; cut into even cubes.","Sauté onion and bloom curry powder for about 30 seconds.","Add vegetables and 400 ml water; cover and simmer for 15 minutes.","Stir in coconut milk, season and cook five minutes until tender."]}},
    {id:"tofu-mushroom",name:{vi:"Đậu hũ xào nấm",en:"Tofu and mushroom stir-fry"},mealType:"lunch",time:20,cost:24000,servings:2,photo:photos.bowl,cuisine:"Asian",tags:["vegetarian","quick"],allergens:["soy","gluten"],ingredients:[["tofu",2,"bìa"],["mushroom",1,"gói"],["scallion",5,"g"],["garlic",1,"tép"],["soy-sauce",8,"ml"],["oil",5,"ml"]],steps:{vi:["Thấm khô đậu, cắt khối; lau sạch nấm và cắt lát.","Áp chảo đậu với ít dầu đến vàng đều rồi để riêng.","Phi tỏi, xào nấm trên lửa lớn cho đến khi nước bay hơi.","Thêm đậu và nước tương, đảo nhẹ 2 phút; rắc hành trước khi ăn."],en:["Pat tofu dry and cube it; wipe mushrooms clean and slice.","Pan-sear tofu in a little oil until golden, then set aside.","Sauté garlic and cook mushrooms over high heat until their moisture evaporates.","Add tofu and soy sauce, toss gently for two minutes and finish with scallion."]}},
    {id:"chicken-salad",name:{vi:"Salad gà xé",en:"Shredded chicken salad"},mealType:"lunch",time:25,cost:32000,servings:2,photo:photos.salad,cuisine:"Vietnamese",tags:["high-protein","light"],allergens:[],ingredients:[["chicken",120,"g"],["lettuce",50,"g"],["cabbage",80,"g"],["carrot",40,"g"],["lime",1,"quả"],["sugar",5,"g"]],steps:{vi:["Luộc gà với chút muối 12–15 phút; để nguội rồi xé sợi.","Thái mỏng bắp cải, cà rốt và xà lách; ngâm nước lạnh 5 phút.","Pha nước cốt chanh, đường, nước mắm và 2 thìa nước.","Trộn rau với gà và nước trộn ngay trước khi ăn."],en:["Poach chicken with a little salt for 12–15 minutes; cool and shred.","Thinly slice cabbage, carrot and lettuce; soak in cold water for five minutes.","Mix lime juice, sugar, fish sauce and two spoons of water.","Toss vegetables with chicken and dressing just before serving."]}},
    {id:"fish-tomato",name:{vi:"Cá basa sốt cà",en:"Basa fish in tomato sauce"},mealType:"dinner",time:25,cost:29000,servings:2,photo:photos.bowl,cuisine:"Vietnamese",tags:["high-protein","budget"],allergens:["seafood"],ingredients:[["fish",180,"g"],["tomato",2,"quả"],["scallion",5,"g"],["garlic",1,"tép"],["fish-sauce",8,"ml"],["oil",5,"ml"]],steps:{vi:["Thấm khô cá, ướp chút muối và tiêu 5 phút.","Áp chảo cá hai mặt đến khi vàng nhẹ, gắp ra đĩa.","Phi tỏi, thêm cà chua và 3 thìa nước, nấu thành sốt mềm.","Cho cá vào om nhỏ lửa 5 phút, nêm nước mắm và rắc hành."],en:["Pat fish dry and season lightly with salt and pepper for five minutes.","Sear both sides until lightly golden and transfer to a plate.","Sauté garlic, add tomatoes and three spoons of water; cook into a soft sauce.","Return fish and simmer for five minutes; season with fish sauce and scallion."]}},
    {id:"banh-mi-egg",name:{vi:"Bánh mì trứng ốp la",en:"Fried egg baguette"},mealType:"breakfast",time:10,cost:10000,servings:1,photo:photos.toast,cuisine:"Vietnamese",tags:["quick","budget"],allergens:["eggs","gluten"],ingredients:[["bread",1,"ổ"],["egg",1,"quả"],["cucumber",20,"g"],["scallion",3,"g"],["oil",4,"ml"]],steps:{vi:["Rạch bánh mì theo chiều dọc, làm nóng trong lò hoặc chảo khô.","Làm nóng ít dầu, chiên trứng đến độ chín mong muốn.","Thái dưa leo mỏng và rửa sạch hành lá.","Kẹp trứng, dưa leo và hành vào bánh mì; dùng khi còn ấm."],en:["Split the baguette lengthwise and warm it in an oven or dry pan.","Fry the egg in a little oil to your preferred doneness.","Slice cucumber thinly and wash the scallion.","Fill the baguette with egg, cucumber and scallion; serve warm."]}},
    {id:"potato-egg-hash",name:{vi:"Khoai tây xào trứng",en:"Potato and egg hash"},mealType:"breakfast",time:22,cost:16000,servings:1,photo:photos.bowl,cuisine:"Vietnamese",tags:["budget","vegetarian"],allergens:["eggs"],ingredients:[["potato",150,"g"],["egg",1,"quả"],["onion",0.25,"củ"],["scallion",5,"g"],["oil",8,"ml"]],steps:{vi:["Gọt khoai, thái lát mỏng và ngâm nước 5 phút rồi để ráo.","Phi hành tây với dầu, cho khoai vào đảo và thêm 2 thìa nước.","Đậy nắp nấu nhỏ lửa 8–10 phút đến khi khoai mềm.","Đập trứng vào đảo tơi, nêm muối tiêu và rắc hành lá."],en:["Peel and thinly slice potato; soak for five minutes and drain.","Sauté onion in oil, add potato and two spoons of water.","Cover and cook over low heat for 8–10 minutes until tender.","Add egg and scramble through; season and garnish with scallion."]}},
    {id:"chicken-lemongrass",name:{vi:"Gà xào sả",en:"Lemongrass-style chicken stir-fry"},mealType:"dinner",time:25,cost:31000,servings:2,photo:photos.chicken,cuisine:"Vietnamese",tags:["high-protein","meal-prep"],allergens:["soy"],ingredients:[["chicken",180,"g"],["garlic",2,"tép"],["chili",1,"trái"],["fish-sauce",8,"ml"],["sugar",4,"g"],["oil",5,"ml"]],steps:{vi:["Thái gà thành miếng vừa; băm tỏi và thái lát ớt nếu dùng.","Ướp gà với nước mắm, đường, tỏi trong 10 phút.","Làm nóng chảo, xào gà trên lửa vừa đến khi chín hoàn toàn.","Đảo thêm 1 phút cho nước sốt áo quanh gà; nêm lại và dùng với cơm."],en:["Cut chicken into bite-size pieces; mince garlic and slice chili if using.","Marinate chicken with fish sauce, sugar and garlic for ten minutes.","Heat a pan and stir-fry chicken over medium heat until fully cooked.","Toss one more minute to glaze the chicken; adjust seasoning and serve with rice."]}},
    {id:"beef-potato",name:{vi:"Bò hầm khoai tây nhanh",en:"Quick beef and potato stew"},mealType:"dinner",time:40,cost:42000,servings:2,photo:photos.soup,cuisine:"Vietnamese",tags:["comfort","batch-cook"],allergens:[],ingredients:[["beef",120,"g"],["potato",150,"g"],["carrot",80,"g"],["tomato",1,"quả"],["onion",0.5,"củ"],["salt",3,"g"]],steps:{vi:["Thái bò và rau củ thành miếng vừa ăn.","Áp chảo bò với chút dầu cho săn, thêm hành và cà chua.","Cho khoai tây, cà rốt và 700 ml nước vào nồi.","Hầm nhỏ lửa 25 phút đến khi rau mềm; nêm muối và tiêu."],en:["Cut beef and vegetables into bite-size pieces.","Brown beef in a little oil, then add onion and tomato.","Add potato, carrot and 700 ml water to the pot.","Simmer for 25 minutes until vegetables are tender; season with salt and pepper."]}},
    {id:"noodle-soup-chicken",name:{vi:"Mì nước gà rau cải",en:"Chicken noodle soup with greens"},mealType:"lunch",time:25,cost:26000,servings:1,photo:photos.noodles,cuisine:"Asian",tags:["comfort","quick"],allergens:["gluten"],ingredients:[["instant-noodle",1,"gói"],["chicken",80,"g"],["spinach",40,"g"],["ginger",5,"g"],["scallion",5,"g"],["salt",2,"g"]],steps:{vi:["Đun 500 ml nước với vài lát gừng; thêm gà thái mỏng.","Nấu gà 8–10 phút đến khi chín; nêm nước dùng vừa ăn.","Cho mì vào nấu theo thời gian trên gói.","Thêm rau cải vào 1 phút cuối; rắc hành trước khi dùng."],en:["Simmer 500 ml water with sliced ginger; add thinly sliced chicken.","Cook chicken for 8–10 minutes until done and season the broth.","Add noodles and cook according to the packet.","Add greens for the final minute and garnish with scallion."]}},
    {id:"fresh-spring-rolls",name:{vi:"Cuốn rau trứng",en:"Fresh vegetable and egg rolls"},mealType:"snack",time:20,cost:18000,servings:2,photo:photos.salad,cuisine:"Vietnamese",tags:["light","no-cook"],allergens:["eggs","peanuts"],ingredients:[["egg",1,"quả"],["lettuce",40,"g"],["cucumber",40,"g"],["carrot",30,"g"],["peanuts",10,"g"],["lime",0.5,"quả"]],steps:{vi:["Chiên trứng thành lớp mỏng, để nguội rồi thái sợi.","Rửa rau, thái dưa leo và cà rốt thành que nhỏ.","Nhúng bánh tráng nhanh qua nước ấm, đặt rau và trứng lên một đầu.","Cuốn chặt tay, rắc đậu phộng giã và chấm nước mắm chanh."],en:["Cook a thin omelette, cool it and slice into strips.","Wash greens; cut cucumber and carrot into thin sticks.","Quickly dip rice paper in warm water and layer vegetables and egg near one edge.","Roll tightly, top with crushed peanuts and dip in lime fish sauce."]}},
    {id:"avocado-egg-toast",name:{vi:"Bánh mì bơ trứng",en:"Avocado egg toast"},mealType:"breakfast",time:12,cost:22000,servings:1,photo:photos.toast,cuisine:"Western",tags:["quick","vegetarian"],allergens:["eggs","gluten"],ingredients:[["bread",1,"ổ"],["avocado",0.5,"quả"],["egg",1,"quả"],["lime",0.25,"quả"],["salt",1,"g"]],steps:{vi:["Nướng hoặc áp chảo bánh mì đến khi vàng giòn.","Nghiền bơ với nước cốt chanh và chút muối.","Chiên trứng ốp la hoặc luộc lòng đào tùy sở thích.","Phết bơ lên bánh, đặt trứng lên trên và dùng ngay."],en:["Toast or pan-grill bread until crisp and golden.","Mash avocado with lime juice and a pinch of salt.","Fry or soft-boil the egg to your preference.","Spread avocado on toast, top with egg and serve immediately."]}},
    {id:"corn-egg-soup",name:{vi:"Súp bắp trứng",en:"Sweet corn egg drop soup"},mealType:"snack",time:18,cost:16000,servings:2,photo:photos.soup,cuisine:"Asian",tags:["quick","comfort"],allergens:["eggs"],ingredients:[["corn",1,"trái"],["egg",1,"quả"],["carrot",30,"g"],["scallion",5,"g"],["salt",2,"g"]],steps:{vi:["Tách hạt bắp; cà rốt thái hạt lựu.","Đun bắp và cà rốt với 600 ml nước trong 10 phút.","Đánh tan trứng, rót chậm thành dòng vào nồi đang sôi nhẹ.","Khuấy một chiều cho vân trứng, nêm muối và rắc hành."],en:["Remove corn kernels; dice the carrot.","Simmer corn and carrot in 600 ml water for ten minutes.","Beat the egg and slowly drizzle it into the gently simmering pot.","Stir once to form ribbons, season with salt and garnish with scallion."]}},
    {id:"stir-fried-cabbage",name:{vi:"Bắp cải xào trứng",en:"Cabbage and egg stir-fry"},mealType:"lunch",time:15,cost:14000,servings:1,photo:photos.bowl,cuisine:"Vietnamese",tags:["quick","budget"],allergens:["eggs"],ingredients:[["cabbage",120,"g"],["egg",1,"quả"],["garlic",1,"tép"],["fish-sauce",5,"ml"],["oil",5,"ml"]],steps:{vi:["Thái bắp cải sợi mỏng, rửa sạch và để ráo.","Phi tỏi với dầu, cho bắp cải vào xào lửa lớn 3 phút.","Gạt rau sang bên, đập trứng vào chảo và đảo tơi.","Trộn đều, nêm nước mắm và tắt bếp khi rau vừa mềm."],en:["Thinly shred the cabbage, wash and drain well.","Sauté garlic in oil, add cabbage and stir-fry over high heat for three minutes.","Push cabbage aside, add egg and scramble.","Combine, season with fish sauce and turn off heat while cabbage is still crisp-tender."]}},
    {id:"pork-tomato-noodles",name:{vi:"Bún thịt bằm cà chua",en:"Rice noodles with pork tomato broth"},mealType:"lunch",time:25,cost:25000,servings:1,photo:photos.noodles,cuisine:"Vietnamese",tags:["comfort","quick"],allergens:[],ingredients:[["rice-noodle",150,"g"],["minced-pork",60,"g"],["tomato",1,"quả"],["scallion",5,"g"],["fish-sauce",5,"ml"],["salt",2,"g"]],steps:{vi:["Chần bún trong nước sôi theo hướng dẫn, để ráo.","Xào thịt bằm với hành đến săn, thêm cà chua cắt múi.","Rót 450 ml nước, nấu sôi 8 phút và nêm nước mắm.","Cho bún vào tô, chan nước dùng và thêm hành lá."],en:["Blanch rice noodles according to the packet and drain.","Cook pork with scallion until no longer pink, then add tomato wedges.","Pour in 450 ml water, simmer eight minutes and season with fish sauce.","Place noodles in a bowl, ladle over broth and finish with scallion."]}},
    {id:"grilled-chicken-salad-bowl",name:{vi:"Bowl gà rau củ",en:"Chicken and veggie bowl"},mealType:"lunch",time:22,cost:34000,servings:1,photo:photos.salad,cuisine:"Western",tags:["high-protein","balanced"],allergens:["sesame"],ingredients:[["chicken",120,"g"],["rice",100,"g"],["broccoli",60,"g"],["carrot",30,"g"],["sesame",3,"g"],["soy-sauce",5,"ml"]],steps:{vi:["Nấu cơm và hấp bông cải cùng cà rốt 5 phút.","Ướp gà với nước tương và tiêu, áp chảo chín đều.","Thái gà thành lát; xếp cơm, rau và gà vào tô.","Rắc mè rang và dùng cùng nước tương chanh nhẹ."],en:["Cook rice and steam broccoli with carrot for five minutes.","Season chicken with soy sauce and pepper, then pan-sear until cooked.","Slice chicken and arrange rice, vegetables and chicken in a bowl.","Sprinkle sesame and serve with a light soy-lime dip."]}},
    {id:"egg-tofu-bowl",name:{vi:"Đậu hũ trứng sốt nước tương",en:"Tofu and egg soy bowl"},mealType:"dinner",time:18,cost:19000,servings:1,photo:photos.bowl,cuisine:"Asian",tags:["quick","vegetarian"],allergens:["soy","eggs"],ingredients:[["tofu",1,"bìa"],["egg",1,"quả"],["soy-sauce",8,"ml"],["scallion",5,"g"],["oil",5,"ml"],["rice",120,"g"]],steps:{vi:["Nấu cơm; cắt đậu thành miếng vuông và thấm khô.","Áp chảo đậu vàng nhẹ, thêm nước tương pha cùng 2 thìa nước.","Đập trứng vào khoảng trống trong chảo, đậy nắp 2 phút.","Rưới sốt lên cơm, xếp đậu và trứng, thêm hành lá."],en:["Cook rice; cube tofu and pat it dry.","Pan-sear tofu until lightly golden; add soy sauce mixed with two spoons of water.","Crack egg into an open space in the pan and cover for two minutes.","Spoon sauce over rice, top with tofu and egg, and garnish with scallion."]}},
    {id:"tomato-soup-tofu",name:{vi:"Canh cà chua đậu hũ",en:"Tomato tofu soup"},mealType:"dinner",time:18,cost:16000,servings:2,photo:photos.soup,cuisine:"Vietnamese",tags:["vegetarian","budget"],allergens:["soy"],ingredients:[["tofu",1,"bìa"],["tomato",2,"quả"],["scallion",5,"g"],["salt",2,"g"],["fish-sauce",3,"ml"]],steps:{vi:["Cắt đậu hũ thành khối, cà chua bổ múi cau.","Đun sôi 600 ml nước, thêm cà chua và nấu 5 phút.","Cho đậu vào nhẹ tay để không vỡ; nấu thêm 4 phút.","Nêm muối, nước mắm vừa ăn; rắc hành lá."],en:["Cube tofu and cut tomatoes into wedges.","Bring 600 ml water to a boil, add tomatoes and cook for five minutes.","Gently add tofu and simmer for four more minutes.","Season with salt and fish sauce; garnish with scallion."]}},
    {id:"fried-fish-rice",name:{vi:"Cá áp chảo ăn cơm",en:"Pan-fried fish with rice"},mealType:"dinner",time:20,cost:28000,servings:1,photo:photos.bowl,cuisine:"Vietnamese",tags:["high-protein","quick"],allergens:["seafood"],ingredients:[["fish",150,"g"],["rice",130,"g"],["cucumber",40,"g"],["lime",0.5,"quả"],["oil",5,"ml"],["salt",2,"g"]],steps:{vi:["Nấu cơm; thấm khô cá và nêm muối tiêu hai mặt.","Đun nóng chảo với dầu, áp chảo cá 3–4 phút mỗi mặt.","Kiểm tra cá chín đục và dễ tách bằng nĩa.","Dọn cá với cơm, dưa leo và nước chấm chanh."],en:["Cook rice; pat fish dry and season both sides with salt and pepper.","Heat oil and pan-fry fish for 3–4 minutes per side.","Check that fish is opaque and flakes easily with a fork.","Serve with rice, cucumber and lime dipping sauce."]}},
    {id:"mushroom-omelette",name:{vi:"Trứng cuộn nấm",en:"Mushroom omelette"},mealType:"breakfast",time:14,cost:17000,servings:1,photo:photos.toast,cuisine:"Vietnamese",tags:["quick","vegetarian"],allergens:["eggs"],ingredients:[["egg",2,"quả"],["mushroom",0.5,"gói"],["scallion",5,"g"],["oil",5,"ml"],["salt",1,"g"]],steps:{vi:["Lau sạch nấm, thái lát; đánh trứng cùng muối và hành lá.","Xào nấm với ít dầu đến khi mềm, gắp ra.","Đổ trứng vào chảo chống dính, nghiêng chảo cho trứng dàn mỏng.","Khi trứng gần đông, cho nấm vào giữa rồi cuộn lại."],en:["Wipe and slice mushrooms; beat eggs with salt and scallion.","Sauté mushrooms in a little oil until tender, then remove.","Pour eggs into a non-stick pan and tilt to spread thinly.","When nearly set, add mushrooms to the centre and roll the omelette."]}},
    {id:"peanut-noodle-salad",name:{vi:"Bún trộn rau đậu phộng",en:"Rice noodle peanut salad"},mealType:"lunch",time:15,cost:18000,servings:1,photo:photos.salad,cuisine:"Vietnamese",tags:["quick","vegetarian"],allergens:["peanuts"],ingredients:[["rice-noodle",130,"g"],["lettuce",30,"g"],["cucumber",40,"g"],["peanuts",10,"g"],["lime",0.5,"quả"],["sugar",3,"g"]],steps:{vi:["Chần bún, xả nước mát và để ráo.","Thái dưa leo, xé xà lách; rang đậu phộng và giã dập.","Pha chanh, đường, chút muối và 2 thìa nước thành nước trộn.","Trộn bún với rau và nước sốt, rắc đậu phộng trước khi ăn."],en:["Blanch noodles, rinse with cool water and drain.","Slice cucumber, tear lettuce; toast and crush peanuts.","Whisk lime juice, sugar, a pinch of salt and two spoons of water.","Toss noodles with vegetables and dressing; sprinkle peanuts before serving."]}},
    {id:"coconut-pumpkin-curry",name:{vi:"Bí đỏ cà ri đậu hũ",en:"Pumpkin tofu coconut curry"},mealType:"dinner",time:28,cost:26000,servings:2,photo:photos.soup,cuisine:"Asian",tags:["vegetarian","batch-cook"],allergens:["soy"],ingredients:[["pumpkin",180,"g"],["tofu",1,"bìa"],["coconut-milk",80,"ml"],["curry-powder",8,"g"],["onion",0.5,"củ"],["rice",150,"g"]],steps:{vi:["Nấu cơm; cắt bí đỏ và đậu hũ thành khối vừa ăn.","Phi hành với bột cà ri đến thơm, thêm bí và 300 ml nước.","Nấu 12 phút đến khi bí gần mềm, cho đậu hũ vào nhẹ tay.","Thêm nước cốt dừa, nêm vừa ăn và nấu thêm 5 phút."],en:["Cook rice; cube pumpkin and tofu into bite-size pieces.","Sauté onion with curry powder until fragrant, add pumpkin and 300 ml water.","Cook for twelve minutes until almost tender; gently add tofu.","Stir in coconut milk, season and simmer five more minutes."]}},
    {id:"banana-yogurt-bowl",name:{vi:"Sữa chua chuối yến mạch",en:"Banana yogurt oat bowl"},mealType:"snack",time:5,cost:14000,servings:1,photo:photos.bowl,cuisine:"Western",tags:["no-cook","vegetarian"],allergens:["dairy","gluten"],ingredients:[["yogurt",1,"hũ"],["banana",1,"quả"],["oats",20,"g"],["peanuts",5,"g"]],steps:{vi:["Bóc vỏ chuối và thái lát vừa ăn.","Cho sữa chua vào bát, thêm chuối và yến mạch.","Rắc đậu phộng rang nếu không dị ứng.","Ăn ngay hoặc để lạnh 10 phút cho yến mạch mềm."],en:["Peel and slice the banana.","Spoon yogurt into a bowl and top with banana and oats.","Add toasted peanuts if safe for you.","Eat right away or chill ten minutes to soften the oats."]}},
    {id:"vegetable-fried-rice",name:{vi:"Cơm chiên rau củ",en:"Vegetable fried rice"},mealType:"lunch",time:15,cost:13000,servings:1,photo:photos.rice,cuisine:"Asian",tags:["quick","vegetarian","budget"],allergens:["soy"],ingredients:[["rice",150,"g"],["carrot",30,"g"],["corn",0.5,"trái"],["cabbage",30,"g"],["soy-sauce",5,"ml"],["oil",5,"ml"]],steps:{vi:["Tách hạt bắp, thái hạt lựu cà rốt và bắp cải.","Làm nóng dầu, xào rau củ 3 phút cho vừa mềm.","Thêm cơm nguội, dằm tơi và đảo trên lửa lớn.","Nêm nước tương, đảo nóng 1 phút rồi dùng."],en:["Remove corn kernels; dice carrot and cabbage.","Heat oil and stir-fry vegetables for three minutes until just tender.","Add cold rice, break up clumps and toss over high heat.","Season with soy sauce, stir for one minute and serve."]}},
    {id:"tomato-beef-soup",name:{vi:"Canh cà chua thịt bò",en:"Tomato beef soup"},mealType:"dinner",time:20,cost:28000,servings:2,photo:photos.soup,cuisine:"Vietnamese",tags:["quick","high-protein"],allergens:[],ingredients:[["beef",80,"g"],["tomato",2,"quả"],["scallion",5,"g"],["ginger",3,"g"],["salt",2,"g"]],steps:{vi:["Thái bò thật mỏng; thái cà chua múi cau và gừng sợi.","Đun 600 ml nước với cà chua trong 5 phút.","Cho bò và gừng vào, nấu 2–3 phút đến khi bò vừa chín.","Nêm muối, rắc hành lá và dùng nóng."],en:["Slice beef very thinly; cut tomatoes into wedges and ginger into matchsticks.","Simmer tomatoes in 600 ml water for five minutes.","Add beef and ginger; cook two to three minutes until just done.","Season with salt, garnish with scallion and serve hot."]}},
    {id:"fish-sauce-chicken-wrap",name:{vi:"Cuốn gà rau xà lách",en:"Chicken lettuce wraps"},mealType:"lunch",time:20,cost:30000,servings:2,photo:photos.salad,cuisine:"Vietnamese",tags:["high-protein","light"],allergens:["soy"],ingredients:[["chicken",100,"g"],["lettuce",50,"g"],["cucumber",40,"g"],["carrot",30,"g"],["fish-sauce",5,"ml"],["lime",0.5,"quả"]],steps:{vi:["Luộc hoặc áp chảo gà đến chín rồi xé sợi.","Thái cà rốt và dưa leo thành que nhỏ; rửa lá xà lách nguyên.","Pha nước chấm chanh, nước mắm, đường và chút nước.","Cho gà và rau vào lá xà lách, cuốn gọn và chấm sốt."],en:["Poach or pan-cook chicken until fully cooked, then shred.","Cut carrot and cucumber into sticks; wash whole lettuce leaves.","Mix lime, fish sauce, sugar and a splash of water for dipping.","Fill lettuce leaves with chicken and vegetables, roll and dip."]}},
    {id:"sausage-potato-pan",name:{vi:"Xúc xích xào khoai tây",en:"Sausage and potato skillet"},mealType:"dinner",time:22,cost:24000,servings:2,photo:photos.bowl,cuisine:"Western",tags:["quick","budget"],allergens:[],ingredients:[["sausage",1,"gói"],["potato",120,"g"],["onion",0.5,"củ"],["bell-pepper",0.5,"trái"],["oil",5,"ml"],["salt",1,"g"]],steps:{vi:["Thái xúc xích, khoai tây, hành và ớt chuông thành miếng vừa.","Áp chảo khoai với ít dầu và 3 thìa nước, đậy nắp 8 phút.","Thêm xúc xích, hành và ớt chuông, đảo đều.","Nấu đến khi khoai mềm và xúc xích nóng; nêm muối tiêu."],en:["Slice sausage, potato, onion and bell pepper into bite-size pieces.","Pan-cook potato in a little oil and three spoons of water, covered for eight minutes.","Add sausage, onion and bell pepper; toss well.","Cook until potato is tender and sausage hot; season to taste."]}},
    {id:"pasta-garlic-mushroom",name:{vi:"Mì Ý nấm tỏi",en:"Garlic mushroom pasta"},mealType:"dinner",time:22,cost:28000,servings:2,photo:photos.pasta,cuisine:"Western",tags:["vegetarian","quick"],allergens:["gluten"],ingredients:[["pasta",150,"g"],["mushroom",1,"gói"],["garlic",2,"tép"],["oil",8,"ml"],["cheese",2,"lát"],["salt",2,"g"]],steps:{vi:["Luộc mì theo hướng dẫn, chừa lại một ít nước luộc.","Thái nấm, băm tỏi; phi tỏi với dầu trên lửa vừa.","Cho nấm vào xào đến mềm, thêm mì và 2 thìa nước luộc.","Trộn đều, nêm muối tiêu và thêm phô mai nếu thích."],en:["Cook pasta according to the packet and reserve a little pasta water.","Slice mushrooms and mince garlic; sauté garlic in oil over medium heat.","Add mushrooms and cook until tender, then add pasta and two spoons of pasta water.","Toss well, season and add cheese if desired."]}},
    {id:"egg-drop-tomato-noodles",name:{vi:"Mì trứng cà chua",en:"Tomato egg noodle soup"},mealType:"lunch",time:14,cost:12000,servings:1,photo:photos.noodles,cuisine:"Asian",tags:["quick","budget"],allergens:["eggs","gluten"],ingredients:[["instant-noodle",1,"gói"],["egg",1,"quả"],["tomato",1,"quả"],["scallion",5,"g"],["salt",1,"g"]],steps:{vi:["Đun sôi 450 ml nước, cho cà chua cắt múi vào nấu 4 phút.","Thêm mì và nấu theo hướng dẫn trên gói.","Đánh tan trứng, rót thành dòng mỏng vào nồi đang sôi nhẹ.","Khuấy nhẹ, nêm gói gia vị vừa phải và thêm hành lá."],en:["Bring 450 ml water to a boil; simmer tomato wedges for four minutes.","Add noodles and cook according to the packet.","Beat egg and drizzle slowly into the gently simmering pot.","Stir softly, season lightly with the packet and add scallion."]}},
    {id:"orange-yogurt-smoothie",name:{vi:"Sinh tố cam sữa chua",en:"Orange yogurt smoothie"},mealType:"snack",time:5,cost:16000,servings:1,photo:photos.bowl,cuisine:"Western",tags:["quick","no-cook"],allergens:["dairy"],ingredients:[["orange",1,"quả"],["yogurt",1,"hũ"],["milk",50,"ml"],["sugar",3,"g"]],steps:{vi:["Bóc cam, bỏ hạt và tách múi.","Cho cam, sữa chua, sữa tươi vào máy xay.","Xay 30–45 giây đến khi mịn; nếm thử độ ngọt.","Thêm chút đường nếu cần và uống ngay."],en:["Peel the orange, remove seeds and separate segments.","Add orange, yogurt and milk to a blender.","Blend for 30–45 seconds until smooth; taste for sweetness.","Add a little sugar if needed and serve immediately."]}},
    {id:"fish-rice-noodle-bowl",name:{vi:"Bún cá áp chảo",en:"Rice noodles with pan-fried fish"},mealType:"lunch",time:22,cost:30000,servings:1,photo:photos.noodles,cuisine:"Vietnamese",tags:["high-protein","quick"],allergens:["seafood"],ingredients:[["rice-noodle",130,"g"],["fish",100,"g"],["lettuce",20,"g"],["cucumber",30,"g"],["lime",0.5,"quả"],["fish-sauce",5,"ml"]],steps:{vi:["Chần bún rồi để ráo; rửa rau và thái dưa leo.","Nêm cá với chút muối, áp chảo chín vàng hai mặt.","Pha nước chấm chanh, nước mắm, đường và nước lọc.","Xếp bún, rau và cá vào tô, dùng cùng nước chấm."],en:["Blanch noodles and drain; wash lettuce and slice cucumber.","Season fish lightly and pan-fry until golden and cooked through.","Mix lime, fish sauce, sugar and water for the dipping sauce.","Arrange noodles, vegetables and fish in a bowl and serve with sauce."]}},
    {id:"cabbage-tofu-rolls",name:{vi:"Bắp cải cuộn đậu hũ",en:"Cabbage tofu rolls"},mealType:"dinner",time:30,cost:20000,servings:2,photo:photos.bowl,cuisine:"Vietnamese",tags:["vegetarian","meal-prep"],allergens:["soy"],ingredients:[["cabbage",4,"lá"],["tofu",1,"bìa"],["carrot",40,"g"],["mushroom",0.5,"gói"],["soy-sauce",5,"ml"],["scallion",5,"g"]],steps:{vi:["Tách lá bắp cải, chần nhanh 1 phút cho mềm và để ráo.","Nghiền đậu hũ, trộn với cà rốt băm, nấm và chút nước tương.","Cho nhân vào lá bắp cải, gấp hai bên và cuộn chặt.","Hấp cuộn 12 phút; dùng với nước tương chanh."],en:["Separate cabbage leaves, blanch for one minute until pliable and drain.","Mash tofu and mix with minced carrot, mushroom and a little soy sauce.","Place filling on each leaf, fold sides in and roll tightly.","Steam for twelve minutes and serve with soy-lime dip."]}},
    {id:"banana-milk-oats",name:{vi:"Yến mạch chuối sữa",en:"Banana milk oats"},mealType:"breakfast",time:10,cost:12000,servings:1,photo:photos.bowl,cuisine:"Western",tags:["quick","vegetarian"],allergens:["dairy","gluten"],ingredients:[["oats",50,"g"],["milk",150,"ml"],["banana",0.5,"quả"],["sugar",3,"g"]],steps:{vi:["Cho yến mạch và sữa vào nồi nhỏ.","Nấu lửa nhỏ 5–7 phút, khuấy thường xuyên đến độ sánh mong muốn.","Cắt chuối thành lát; tắt bếp và nêm chút đường nếu thích.","Múc ra bát, xếp chuối lên trên và dùng ấm."],en:["Add oats and milk to a small saucepan.","Cook over low heat for 5–7 minutes, stirring until creamy.","Slice banana; turn off heat and sweeten lightly if desired.","Spoon into a bowl, top with banana and serve warm."]}},
    {id:"beef-cucumber-wrap",name:{vi:"Bánh mì bò dưa leo",en:"Beef cucumber baguette"},mealType:"lunch",time:18,cost:30000,servings:1,photo:photos.toast,cuisine:"Vietnamese",tags:["quick","high-protein"],allergens:["gluten","soy"],ingredients:[["bread",1,"ổ"],["beef",70,"g"],["cucumber",30,"g"],["lettuce",15,"g"],["soy-sauce",5,"ml"],["oil",3,"ml"]],steps:{vi:["Thái bò thật mỏng, ướp nước tương và tiêu 5 phút.","Áp chảo bò trên lửa lớn trong 2–3 phút đến khi vừa chín.","Rạch bánh mì, xếp xà lách và dưa leo vào trong.","Thêm bò nóng, rưới nước chảo và dùng ngay."],en:["Slice beef thinly and marinate with soy sauce and pepper for five minutes.","Sear over high heat for two to three minutes until just cooked.","Split baguette and layer with lettuce and cucumber.","Add hot beef, spoon over pan juices and serve right away."]}},
    {id:"vegetable-egg-noodle-stirfry",name:{vi:"Mì xào trứng rau cải",en:"Egg and greens noodle stir-fry"},mealType:"dinner",time:16,cost:16000,servings:1,photo:photos.noodles,cuisine:"Asian",tags:["quick","budget"],allergens:["eggs","gluten","soy"],ingredients:[["instant-noodle",1,"gói"],["egg",1,"quả"],["spinach",40,"g"],["carrot",20,"g"],["soy-sauce",5,"ml"],["oil",5,"ml"]],steps:{vi:["Chần mì vừa mềm, để ráo; đánh tan trứng.","Xào cà rốt với chút dầu 2 phút, thêm rau cải.","Gạt rau sang bên, đổ trứng vào đảo tơi rồi cho mì vào.","Nêm ít nước tương, đảo nóng đều và dùng ngay."],en:["Blanch noodles until just tender and drain; beat the egg.","Stir-fry carrot in a little oil for two minutes, then add greens.","Push vegetables aside, scramble egg and add noodles.","Season with a little soy sauce, toss until hot and serve immediately."]}},
    {id:"tomato-tofu-rice",name:{vi:"Cơm đậu hũ cà chua",en:"Tofu tomato rice bowl"},mealType:"lunch",time:18,cost:17000,servings:1,photo:photos.rice,cuisine:"Vietnamese",tags:["vegetarian","budget"],allergens:["soy"],ingredients:[["rice",130,"g"],["tofu",1,"bìa"],["tomato",1,"quả"],["scallion",5,"g"],["fish-sauce",3,"ml"],["oil",5,"ml"]],steps:{vi:["Nấu cơm; cắt đậu hũ và cà chua thành miếng.","Áp chảo đậu hũ vàng nhẹ rồi gắp ra.","Nấu cà chua với 2 thìa nước đến mềm, nêm nước mắm.","Cho đậu vào sốt 3 phút; múc lên cơm và thêm hành."],en:["Cook rice; cube tofu and tomato.","Pan-sear tofu until lightly golden and remove.","Cook tomato with two spoons of water until soft; season with fish sauce.","Simmer tofu in the sauce for three minutes, spoon over rice and garnish with scallion."]}},
    {id:"fruit-oat-yogurt",name:{vi:"Bát trái cây yến mạch",en:"Fruit oat yogurt bowl"},mealType:"snack",time:5,cost:19000,servings:1,photo:photos.salad,cuisine:"Western",tags:["no-cook","vegetarian"],allergens:["dairy","gluten"],ingredients:[["yogurt",1,"hũ"],["apple",0.5,"quả"],["banana",0.5,"quả"],["oats",15,"g"]],steps:{vi:["Rửa táo, bỏ hạt và cắt hạt lựu; thái chuối lát.","Cho sữa chua vào bát, xếp táo và chuối lên trên.","Rắc yến mạch để tạo độ giòn.","Dùng ngay hoặc để lạnh ngắn trước khi ăn."],en:["Wash and dice apple; slice banana.","Spoon yogurt into a bowl and top with the fruit.","Sprinkle oats over the top for crunch.","Serve immediately or chill briefly before eating."]}},
    {id:"ginger-pork-rice",name:{vi:"Thịt heo xào gừng",en:"Ginger pork rice bowl"},mealType:"dinner",time:20,cost:26000,servings:1,photo:photos.rice,cuisine:"Vietnamese",tags:["quick","high-protein"],allergens:["soy"],ingredients:[["pork",100,"g"],["ginger",8,"g"],["rice",130,"g"],["soy-sauce",8,"ml"],["garlic",1,"tép"],["oil",5,"ml"]],steps:{vi:["Thái thịt heo mỏng, gừng thái sợi và băm tỏi.","Ướp thịt với nước tương, gừng và tỏi 5 phút.","Xào thịt trên lửa vừa đến khi chín hoàn toàn và hơi xém cạnh.","Nêm lại, rưới sốt lên cơm nóng và dùng cùng rau nếu có."],en:["Slice pork thinly, cut ginger into matchsticks and mince garlic.","Marinate pork with soy sauce, ginger and garlic for five minutes.","Stir-fry over medium heat until fully cooked and lightly browned.","Adjust seasoning, spoon over rice and serve with any available greens."]}},
    {id:"broccoli-garlic-egg",name:{vi:"Bông cải xào trứng",en:"Broccoli egg stir-fry"},mealType:"lunch",time:15,cost:19000,servings:1,photo:photos.bowl,cuisine:"Asian",tags:["quick","vegetarian"],allergens:["eggs"],ingredients:[["broccoli",100,"g"],["egg",1,"quả"],["garlic",1,"tép"],["soy-sauce",4,"ml"],["oil",5,"ml"]],steps:{vi:["Tách bông cải thành nhánh nhỏ, chần nước sôi 2 phút.","Phi tỏi với dầu, cho bông cải vào đảo nóng.","Đẩy rau sang một bên, cho trứng vào đảo tơi.","Trộn đều, nêm nước tương và dùng với cơm."],en:["Break broccoli into florets and blanch for two minutes.","Sauté garlic in oil and add broccoli to warm through.","Push vegetables aside and scramble the egg.","Combine, season with soy sauce and serve with rice."]}},
    {id:"tomato-pasta-cheese",name:{vi:"Mì Ý sốt cà chua phô mai",en:"Tomato cheese pasta"},mealType:"dinner",time:22,cost:29000,servings:2,photo:photos.pasta,cuisine:"Western",tags:["vegetarian","quick"],allergens:["gluten","dairy"],ingredients:[["pasta",150,"g"],["tomato",2,"quả"],["onion",0.5,"củ"],["cheese",2,"lát"],["garlic",1,"tép"],["oil",5,"ml"]],steps:{vi:["Luộc mì theo hướng dẫn và giữ lại một ít nước luộc.","Phi hành tỏi, thêm cà chua thái nhỏ và nấu mềm 8 phút.","Nghiền nhẹ cà chua, thêm mì và 2 thìa nước luộc.","Tắt bếp, xé phô mai vào đảo tan và dùng nóng."],en:["Cook pasta according to the packet and reserve a little cooking water.","Sauté onion and garlic, add chopped tomatoes and cook eight minutes.","Mash tomatoes lightly, add pasta and two spoons of pasta water.","Turn off heat, stir in torn cheese until melted and serve hot."]}},
    {id:"fish-ginger-noodle-soup",name:{vi:"Bún cá gừng",en:"Ginger fish rice noodle soup"},mealType:"dinner",time:25,cost:28000,servings:1,photo:photos.noodles,cuisine:"Vietnamese",tags:["comfort","high-protein"],allergens:["seafood"],ingredients:[["rice-noodle",130,"g"],["fish",100,"g"],["ginger",8,"g"],["scallion",5,"g"],["lime",0.5,"quả"],["salt",2,"g"]],steps:{vi:["Chần bún, để ráo; gừng thái lát mỏng.","Đun 500 ml nước với gừng 5 phút để lấy mùi thơm.","Cho cá vào nấu nhẹ 5–7 phút đến khi chín và tách thớ.","Nêm muối, cho bún vào tô chan nước dùng và thêm hành, chanh."],en:["Blanch rice noodles and drain; slice ginger thinly.","Simmer ginger in 500 ml water for five minutes to infuse the broth.","Add fish and poach gently for 5–7 minutes until cooked and flaky.","Season with salt, place noodles in a bowl, ladle broth and add scallion and lime."]}},
    {id:"carrot-potato-salad",name:{vi:"Salad khoai tây cà rốt",en:"Potato carrot salad"},mealType:"lunch",time:25,cost:18000,servings:2,photo:photos.salad,cuisine:"Western",tags:["vegetarian","budget"],allergens:["eggs"],ingredients:[["potato",150,"g"],["carrot",60,"g"],["egg",1,"quả"],["yogurt",0.5,"hũ"],["lime",0.25,"quả"],["salt",2,"g"]],steps:{vi:["Luộc khoai tây, cà rốt đến mềm vừa; luộc trứng chín.","Để nguội, cắt khoai và cà rốt thành khối nhỏ; bóc trứng.","Trộn sữa chua với nước cốt chanh, muối và tiêu.","Rưới sốt lên rau củ, thêm trứng cắt lát và để lạnh 10 phút."],en:["Boil potatoes and carrots until just tender; hard-boil the egg.","Cool, cube the vegetables and peel the egg.","Mix yogurt with lime juice, salt and pepper.","Dress vegetables, top with sliced egg and chill for ten minutes."]}},
    {id:"sweet-corn-chicken-rice",name:{vi:"Cơm gà bắp ngọt",en:"Sweet corn chicken rice"},mealType:"lunch",time:20,cost:30000,servings:1,photo:photos.rice,cuisine:"Asian",tags:["quick","balanced"],allergens:[],ingredients:[["rice",130,"g"],["chicken",100,"g"],["corn",0.5,"trái"],["carrot",20,"g"],["soy-sauce",5,"ml"],["oil",4,"ml"]],steps:{vi:["Nấu cơm; tách hạt bắp và thái cà rốt hạt lựu.","Thái gà nhỏ, áp chảo với chút dầu đến khi chín.","Thêm bắp, cà rốt và nước tương, đảo 3 phút.","Dọn gà rau củ lên cơm nóng."],en:["Cook rice; remove corn kernels and dice carrot.","Dice chicken and pan-cook in a little oil until done.","Add corn, carrot and soy sauce; stir-fry for three minutes.","Serve the chicken and vegetables over hot rice."]}},
    {id:"quick-vegetable-soup",name:{vi:"Canh rau củ nhanh",en:"Quick mixed vegetable soup"},mealType:"dinner",time:20,cost:16000,servings:2,photo:photos.soup,cuisine:"Vietnamese",tags:["vegetarian","budget"],allergens:[],ingredients:[["carrot",50,"g"],["potato",80,"g"],["cabbage",70,"g"],["corn",0.5,"trái"],["salt",2,"g"],["scallion",5,"g"]],steps:{vi:["Gọt khoai, cà rốt; thái cùng bắp cải thành miếng vừa ăn.","Đun sôi 700 ml nước, cho khoai và cà rốt vào trước 8 phút.","Thêm bắp và bắp cải, nấu thêm 5 phút đến khi rau vừa mềm.","Nêm muối, rắc hành và dùng nóng."],en:["Peel potato and carrot; cut with cabbage into bite-size pieces.","Bring 700 ml water to a boil; add potato and carrot for eight minutes.","Add corn and cabbage; simmer five minutes until just tender.","Season with salt, garnish with scallion and serve hot."]}},
    {id:"garlic-bread-egg",name:{vi:"Bánh mì bơ tỏi trứng",en:"Garlic toast with egg"},mealType:"breakfast",time:12,cost:15000,servings:1,photo:photos.toast,cuisine:"Western",tags:["quick","budget"],allergens:["eggs","gluten","dairy"],ingredients:[["bread",1,"ổ"],["egg",1,"quả"],["garlic",1,"tép"],["cheese",1,"lát"],["oil",3,"ml"]],steps:{vi:["Băm tỏi, trộn với một thìa dầu và phết lên mặt bánh mì.","Áp chảo bánh mì mặt phết tỏi đến khi thơm và vàng nhẹ.","Chiên trứng, đặt lên bánh mì và phủ phô mai.","Đậy nắp chảo 1 phút cho phô mai mềm rồi dùng nóng."],en:["Mince garlic, mix with a spoon of oil and spread over the bread.","Toast garlic-side down in a pan until fragrant and lightly golden.","Fry an egg, place on the toast and add cheese.","Cover the pan for one minute to soften cheese and serve warm."]}},
    {id:"mushroom-tofu-noodles",name:{vi:"Mì nấm đậu hũ",en:"Mushroom tofu noodles"},mealType:"dinner",time:18,cost:20000,servings:1,photo:photos.noodles,cuisine:"Asian",tags:["quick","vegetarian"],allergens:["gluten","soy"],ingredients:[["instant-noodle",1,"gói"],["tofu",0.5,"bìa"],["mushroom",0.5,"gói"],["scallion",5,"g"],["soy-sauce",4,"ml"],["oil",3,"ml"]],steps:{vi:["Cắt đậu hũ thành miếng nhỏ, thái nấm và hành lá.","Áp chảo đậu hũ vàng nhẹ, cho nấm vào xào thêm 2 phút.","Đun 450 ml nước, nấu mì theo hướng dẫn trên gói.","Cho đậu và nấm lên mì, nêm nhẹ nước tương và thêm hành."],en:["Cube tofu, slice mushrooms and scallion.","Pan-sear tofu until lightly golden, then add mushrooms for two minutes.","Bring 450 ml water to a boil and cook noodles according to the packet.","Top noodles with tofu and mushrooms, season lightly with soy and add scallion."]}},
    {id:"apple-peanut-toast",name:{vi:"Bánh mì táo bơ đậu phộng",en:"Apple peanut butter toast"},mealType:"snack",time:5,cost:14000,servings:1,photo:photos.toast,cuisine:"Western",tags:["no-cook","quick"],allergens:["gluten","peanuts"],ingredients:[["bread",1,"ổ"],["apple",0.5,"quả"],["peanuts",10,"g"],["banana",0.25,"quả"]],steps:{vi:["Nướng nhẹ bánh mì hoặc dùng bánh mì tươi.","Thái táo thành lát mỏng, chuối thành lát tròn.","Phết lớp bơ đậu phộng mỏng nếu có; rải trái cây lên bánh.","Dùng ngay như bữa phụ nhanh, no lâu."],en:["Lightly toast bread or use it fresh.","Slice apple thinly and cut banana into coins.","Spread a thin layer of peanut butter if available and top with fruit.","Serve immediately as a quick, filling snack."]}}
